<div class="topline"><span>MAKE SPACE FOR YOUR DAY</span><span><?= e(date('l, j F Y',strtotime($date))) ?></span></div>
<header class="page-header"><div><h1>A day with intention.</h1><p class="muted">Tasks, habits, routines and appointments, together.</p></div><form class="inline" action="/planner" method="get"><input type="hidden" name="view" value="<?= e($tab) ?>"><label class="sr-only" for="planner-date">Planner date</label><input id="planner-date" type="date" name="date" value="<?= e($date) ?>" required><button class="secondary">View date</button></form></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs" aria-label="Daily planner pages"><?php foreach (['today'=>'Today','tasks'=>'Tasks','habits'=>'Habits','routines'=>'Routines','appointments'=>'Appointments'] as $key=>$label): ?><a href="/planner?view=<?= e($key) ?>&date=<?= e($date) ?>" <?= $tab===$key ? 'class="selected" aria-current="page"' : '' ?>><?= e($label) ?></a><?php endforeach; ?></nav>
<?php
$plannerUrl=fn($day)=>'/planner?'.http_build_query(['view'=>$tab,'date'=>$day,'filter'=>$taskList['filter'],'q'=>$taskList['search']]);
$weekStart=(new DateTimeImmutable($date))->modify('-'.((int)date('N',strtotime($date))-1).' days');
?>
<div class="planner-week-heading"><a href="<?= e($plannerUrl($weekStart->modify('-7 days')->format('Y-m-d'))) ?>" aria-label="Previous week">&larr; Previous week</a><a href="<?= e($plannerUrl(date('Y-m-d'))) ?>">Back to today</a><a href="<?= e($plannerUrl($weekStart->modify('+7 days')->format('Y-m-d'))) ?>" aria-label="Next week">Next week &rarr;</a></div>
<nav class="planner-week" aria-label="Choose a planner day"><?php for ($i=0;$i<7;$i++): $day=$weekStart->modify('+'.$i.' days'); $dayValue=$day->format('Y-m-d'); ?><a href="<?= e($plannerUrl($dayValue)) ?>" <?= $dayValue===$date ? 'aria-current="date"' : '' ?> aria-label="<?= e($day->format('l, j F Y')) ?>"><span><?= e($day->format('D')) ?></span><strong><?= e($day->format('j')) ?></strong><small><?= $dayValue===date('Y-m-d') ? 'Today' : e($day->format('M')) ?></small></a><?php endfor; ?></nav>
<?php if ($tab==='today'): $todayTasks=$dayTasks; $todayRoutines=array_filter($routines,fn($r)=>$r['active'] && in_array((string)date('N',strtotime($date)),explode(',',$r['days']),true)); $todayAppointments=$dayAppointments; ?>
<div class="stats"><section class="card"><p class="muted">Tasks due or undated</p><div class="big-number"><?= e($dayTaskCount) ?></div><small>Up to 200 shown below</small></section><section class="card"><p class="muted">Routines scheduled</p><div class="big-number"><?= count($todayRoutines) ?></div></section><section class="card"><p class="muted">Appointments</p><div class="big-number"><?= count($todayAppointments) ?></div></section></div>
<div class="two-col"><section class="card"><div class="section-heading"><h2>Your next tasks</h2><a href="/planner?view=tasks&amp;date=<?= e($date) ?>">Manage →</a></div><?php if (!$todayTasks): ?><p class="muted">No data yet for this day. Add a task to plan your next step.</p><?php else: foreach ($todayTasks as $task): ?><div class="task-row"><span><strong><?= e($task['title']) ?></strong><small class="<?= $task['due'] && $task['due']<$date ? 'error-text' : '' ?>"><?= e($task['due'] ?? 'No due date') ?><?= $task['due'] && $task['due']<$date ? ' · Overdue' : '' ?></small></span><form method="post" action="/planner/tasks/<?= e($task['id']) ?>/status"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><input type="hidden" name="status" value="done"><button class="secondary">Done</button></form></div><?php endforeach; endif; ?></section><section class="card"><div class="section-heading"><h2>Your schedule</h2><a href="/planner?view=appointments&amp;date=<?= e($date) ?>">Manage →</a></div><?php foreach ($todayRoutines as $r): ?><div class="simple-row"><span><strong><?= e($r['time']) ?> · <?= e($r['title']) ?></strong><small>Routine · <?= $r['checked'] ? 'Completed' : 'Not completed' ?></small></span></div><?php endforeach; ?><?php foreach ($todayAppointments as $a): ?><div class="simple-row"><span><strong><?= e(substr($a['starts_at'],11)) ?> · <?= e($a['title']) ?></strong><small><?= e($a['location']) ?> · Until <?= e($a['ends_at']) ?></small></span></div><?php endforeach; ?><?php if (!$todayRoutines && !$todayAppointments): ?><p class="muted">No data yet. Add a routine or appointment to build your schedule.</p><?php endif; ?></section></div>
<section class="card"><div class="section-heading"><h2>Build a little consistency</h2><a href="/planner?view=habits&amp;date=<?= e($date) ?>">Open habits →</a></div><p class="muted"><?php $activeHabits=array_filter($habits,fn($h)=>$h['active']); ?><?= count($activeHabits) ? count(array_filter($activeHabits,fn($h)=>$h['checked'])).' of '.count($activeHabits).' active habits checked for this day.' : 'No data yet. Choose one habit you want to practice.' ?></p></section>
<?php elseif ($tab==='tasks'): ?>
<div class="two-col"><section class="card"><h2>Tasks</h2><p class="muted">Find your next step. Completing a lesson action also applies its lesson.</p>
<form class="task-filters" action="/planner" method="get" role="search" aria-label="Search tasks"><input type="hidden" name="view" value="tasks"><input type="hidden" name="date" value="<?= e($date) ?>"><label>Search tasks<input type="search" name="q" maxlength="200" value="<?= e($taskList['search']) ?>" placeholder="Search by task title"></label><label>Status<select name="filter"><?php foreach (['all'=>'All tasks','open'=>'Open','overdue'=>'Overdue','done'=>'Completed'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $taskList['filter']===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="secondary">Apply</button></form>
<p class="task-result-count" role="status"><?= count($tasks) ?> of <?= e($taskList['total']) ?> matching tasks<?= $taskList['filter']==='overdue' ? ' - Due before '.e($date) : '' ?>.<?= $taskList['total']>200 ? ' Showing the first 200. Narrow your search to find more.' : '' ?> <?php if ($taskList['filter']!=='all' || $taskList['search']!==''): ?><a href="/planner?view=tasks&amp;date=<?= e($date) ?>">Clear filters</a><?php endif; ?></p><?php if (!$tasks): ?><p class="muted"><?= $taskList['filter']!=='all' || $taskList['search']!=='' ? 'No tasks match these filters. Try another title or status.' : 'No data yet. Add your first task.' ?></p><?php else: foreach ($tasks as $t): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($t['title']) ?></strong><small><?= e($t['due'] ?? 'No due date') ?> · <?= e($t['status']) ?> · <?= e($t['source'] ?? 'manual') ?></small></div><form method="post" action="/planner/tasks/<?= e($t['id']) ?>/status"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><input type="hidden" name="status" value="<?= $t['status']==='done' ? 'open' : 'done' ?>"><button class="secondary"><?= $t['status']==='done' ? 'Reopen' : 'Done' ?></button></form></div><details><summary>Edit task</summary><form class="stack" method="post" action="/planner/tasks/<?= e($t['id']) ?>/edit"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><label>Task<input name="title" maxlength="200" value="<?= e($t['title']) ?>" required></label><label>Due date<input type="date" name="due" value="<?= e($t['due']) ?>"></label><button class="secondary">Save task</button></form></details><?php if ($t['source']!=='lesson'): ?><form method="post" action="/planner/tasks/<?= e($t['id']) ?>/delete" data-confirm="Delete this task?"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><button class="delete">Delete</button></form><?php endif; ?></article><?php endforeach; endif; ?></section><section class="card" id="new-task"><h2>Add a task</h2><form class="stack" action="/planner/tasks" method="post"><?= csrf_field() ?><label>What needs doing?<input name="title" maxlength="200" required></label><label>Due date (optional)<input name="due" type="date"></label><button>Add task</button></form></section></div>
<?php elseif ($tab==='habits'): ?>
<div class="two-col"><section class="card"><h2>Your habits</h2><p class="muted">Check-ins for <?= e($date) ?>. Streaks count consecutive days through today or yesterday.</p><?php if (!$habits): ?><p class="muted">No data yet. Start with one small habit.</p><?php else: foreach ($habits as $h): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($h['title']) ?></strong><small><?= $h['active'] ? 'Active' : 'Paused' ?> · <?= e($h['streak']) ?> day streak · <?= e($h['week_count']) ?>/7 recent check-ins</small></div><?php if ($h['active'] && $date<=date('Y-m-d')): ?><form method="post" action="/planner/habits/<?= e($h['id']) ?>/check"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($date) ?>"><button class="secondary"><?= $h['checked'] ? 'Undo check-in' : 'Check in' ?></button></form><?php endif; ?></div><p class="muted"><?= e($h['notes']) ?></p><details><summary>Edit habit</summary><?php $record=$h; $formType='habits'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/planner/habits/<?= e($h['id']) ?>/delete" data-confirm="Delete this habit and its check-in history?"><?= csrf_field() ?><button class="delete">Delete habit</button></form></article><?php endforeach; endif; ?></section><section class="card"><h2>Add a habit</h2><?php $formType='habits'; require __DIR__.'/record-form.php'; ?></section></div>
<?php elseif ($tab==='routines'): ?>
<div class="two-col"><section class="card"><h2>Your routines</h2><?php if (!$routines): ?><p class="muted">No data yet. Build a routine around your actual week.</p><?php else: foreach ($routines as $r): $scheduled=$r['active'] && in_array((string)date('N',strtotime($date)),explode(',',$r['days']),true); ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($r['time']) ?> · <?= e($r['title']) ?></strong><small><?= e(implode(', ',array_map(fn($d)=>PlannerService::DAYS[(int)$d],explode(',',$r['days'])))) ?> · <?= $r['active'] ? 'Active' : 'Paused' ?></small></div><?php if ($scheduled && $date<=date('Y-m-d')): ?><form action="/planner/routines/<?= e($r['id']) ?>/check" method="post"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($date) ?>"><button class="secondary"><?= $r['checked'] ? 'Undo' : 'Complete' ?></button></form><?php endif; ?></div><details><summary>Edit routine</summary><?php $record=$r; $formType='routines'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/planner/routines/<?= e($r['id']) ?>/delete" data-confirm="Delete this routine and its completion history?"><?= csrf_field() ?><button class="delete">Delete routine</button></form></article><?php endforeach; endif; ?></section><section class="card"><h2>Add a routine</h2><?php $formType='routines'; require __DIR__.'/record-form.php'; ?></section></div>
<?php else: ?>
<div class="two-col"><section class="card"><h2>Appointments</h2><p class="muted">Latest 100 appointments. Reminder times are saved with the appointment.</p><?php if (!$appointments): ?><p class="muted">No data yet. Add an appointment or meeting.</p><?php else: foreach ($appointments as $a): ?><article class="lesson-entry"><strong><?= e($a['title']) ?></strong><small><?= e($a['starts_at']) ?> → <?= e($a['ends_at']) ?> · <?= e($a['status']) ?></small><p class="muted"><?= e($a['location']) ?></p><small>Reminder <?= e($a['reminder_minutes']) ?> minutes before</small><details><summary>Edit appointment</summary><?php $record=$a; $formType='appointments'; require __DIR__.'/record-form.php'; unset($record); ?></details><form action="/planner/appointments/<?= e($a['id']) ?>/delete" method="post" data-confirm="Delete this appointment?"><?= csrf_field() ?><button class="delete">Delete appointment</button></form></article><?php endforeach; endif; ?></section><section class="card"><h2>Add an appointment</h2><?php $formType='appointments'; require __DIR__.'/record-form.php'; ?></section></div>
<?php endif; ?>
